#define SFX_NETWORK_SETUP_QUALIFICATION 1
#include "network_setup_fixture.hpp"
#define SFX_NETWORK_NAVIGATION_ENTRY retained_network_navigation_main
#include "rc11_navigation_tests.cpp"
#undef main
#include <tlhelp32.h>

std::uint64_t network_idle_cpu(HANDLE process){FILETIME created{},exited{},kernel{},user{};check(GetProcessTimes(process,&created,&exited,&kernel,&user)!=FALSE,"owned process CPU counters");ULARGE_INTEGER k{},u{};k.LowPart=kernel.dwLowDateTime;k.HighPart=kernel.dwHighDateTime;u.LowPart=user.dwLowDateTime;u.HighPart=user.dwHighDateTime;return k.QuadPart+u.QuadPart;}
int network_idle(const char* directory){Product panel;try{
    const auto out=std::filesystem::absolute(directory);check(!std::filesystem::exists(out),"retain idle evidence");std::filesystem::create_directories(out);const auto root=win32::installation::canonical_root(network_setup_qualification_root());const auto owner=win32::installation::operator_sid();check(!win32::installation::elevated(),"ordinary fixed-root measurement");win32::installation::verify_runtime_installation(root,owner);
    const auto before=win32::offline_ftn_configuration(root,owner);check(before&&before.value,"saved setup before idle measurement");
    panel=launch(root/L"Bin/SFXControlPanel.exe",L"");panel.window=wait_window(panel.pid,kWindowClass);const auto ready=GetTickCount64()+30000;while(!visible_text_contains(panel.window,L"READY")&&GetTickCount64()<ready)Sleep(10);check(visible_text_contains(panel.window,L"READY"),"idle shipping Runtime ready");
    win32::installation::Handle snapshot(CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0));check(snapshot.get()!=INVALID_HANDLE_VALUE,"owned child snapshot");PROCESSENTRY32W p{sizeof(p)};DWORD pid{};if(Process32FirstW(snapshot.get(),&p))do{if(p.th32ParentProcessID==panel.pid&&std::wstring(p.szExeFile)==L"SFXRuntime.exe"){pid=p.th32ProcessID;break;}}while(Process32NextW(snapshot.get(),&p));check(pid!=0,"owned Runtime child found");const auto receipt=win32::installation::read_receipt(root,owner);win32::installation::verify_installed_program_process(receipt,pid,win32::installation::runtime_program_index);win32::installation::Handle runtime(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,pid));check(bool(runtime),"verified Runtime CPU handle");
    const auto tab=GetDlgItem(panel.window,IDC_MAIN_TAB);SendMessageW(tab,WM_KEYDOWN,VK_HOME,0);SendMessageW(tab,WM_KEYDOWN,VK_RIGHT,0);check(TabCtrl_GetCurSel(tab)==1,"actual BinkP page measured");SYSTEM_INFO system{};GetSystemInfo(&system);std::ofstream report(out/L"cpu.tsv");report<<"state\twall_ms\tlogical_processors\truntime_cpu_ms\tpanel_cpu_ms\truntime_percent\tpanel_percent\n";
    for(const bool minimized:{false,true}){ShowWindow(panel.window,minimized?SW_MINIMIZE:SW_RESTORE);Sleep(2000);const auto began=GetTickCount64(),r=network_idle_cpu(runtime.get()),c=network_idle_cpu(panel.process.get());Sleep(15000);const auto wall=GetTickCount64()-began;const auto r_ms=(network_idle_cpu(runtime.get())-r)/10000.0,c_ms=(network_idle_cpu(panel.process.get())-c)/10000.0;report<<(minimized?"minimized":"visible")<<'\t'<<wall<<'\t'<<system.dwNumberOfProcessors<<'\t'<<r_ms<<'\t'<<c_ms<<'\t'<<r_ms*100/(wall*system.dwNumberOfProcessors)<<'\t'<<c_ms*100/(wall*system.dwNumberOfProcessors)<<'\n';report.flush();check(WaitForSingleObject(runtime.get(),0)==WAIT_TIMEOUT,"Runtime stays alive at idle");}
    ShowWindow(panel.window,SW_RESTORE);render_foreign_png(panel.window,out/L"idle-binkp.png");close_panel(panel);const auto after=win32::offline_ftn_configuration(root,owner);check(after&&after.value&&app::encode_ftn_configuration(*after.value)==app::encode_ftn_configuration(*before.value),"idle sample changes no saved setup");std::cout<<"PASS "<<checks<<" actual shipping idle counter checks; machine-specific normalized observations\n";return 0;
}catch(const std::exception& e){try{close_panel(panel);}catch(...){}std::cerr<<"FAIL idle "<<checks<<": "<<e.what()<<'\n';return 1;}}
int main(int argc,char** argv){if(argc==3&&std::string_view(argv[2])=="--idle")return network_idle(argv[1]);return retained_network_navigation_main(argc,argv);}
